import React, { useEffect, useState } from 'react';
import { getAccessToken } from '../services/spotifyAuth';

const WebPlayer = ({ trackUri }) => {
  const [player, setPlayer] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [deviceId, setDeviceId] = useState(null);

  useEffect(() => {
    const token = getAccessToken(); // Get your access token

    // Load Spotify SDK dynamically
    const loadSpotifySDK = () => {
      const script = document.createElement('script');
      script.src = 'https://sdk.scdn.co/spotify-player.js';
      script.async = true;
      script.onload = initializePlayer; // Initialize player once the script is loaded
      document.body.appendChild(script);
    };

    const initializePlayer = () => {
      if (window.Spotify) {
        const player = new window.Spotify.Player({
          name: 'Track Similarity Player',
          getOAuthToken: (cb) => {
            cb(token);
          },
          volume: 0.5,
        });

        setPlayer(player);

        // Connect to the player
        player.connect();

        // Event listeners for the player
        player.addListener('ready', ({ device_id }) => {
          console.log('Player is ready with Device ID', device_id);
          setDeviceId(device_id);
        });

        player.addListener('not_ready', ({ device_id }) => {
          console.log('Device ID has gone offline', device_id);
        });
      } else {
        console.error('Spotify SDK not found');
      }
    };

    // Load the Spotify SDK if not already loaded
    if (!window.Spotify) {
      loadSpotifySDK();
    } else {
      initializePlayer();
    }
  }, []);

  // Play the selected track when user clicks the "Play" button
  const handlePlay = async () => {
    if (player && trackUri && deviceId) {
      try {
        // Use Spotify API to play the track
        const playUrl = `https://api.spotify.com/v1/me/player/play?device_id=${deviceId}`;
        await fetch(playUrl, {
          method: 'PUT',
          body: JSON.stringify({ uris: [trackUri] }),
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${getAccessToken()}`,
          },
        });
        setIsPlaying(true);
      } catch (error) {
        console.error('Error starting playback:', error);
      }
    }
  };

  return (
    <div>
      <h2>Now Playing</h2>
      {trackUri ? (
        <>
          <p>Track URI: {trackUri}</p>
          <button onClick={handlePlay}>{isPlaying ? 'Playing...' : 'Play Track'}</button>
        </>
      ) : (
        <p>Select a track to play</p>
      )}
    </div>
  );
};

export default WebPlayer;
